draw((0,0)--(0,2)--2*unitsquare--(2,0)--cycle,dashed);
draw((0,2)--4*unitsquare--(2,0)--cycle,dashed);
draw((1,0)--(1,1/3)--0.5*unitsquare--cycle,dashed);
draw((1,2)--(1,2/3)--1.5*unitsquare--cycle,dashed);
